"use client";

import { useState, useEffect } from "react";
import Link from "next/link";
import { usePathname } from "next/navigation";
import { motion, AnimatePresence } from "framer-motion";
import { Menu, X, ArrowRight } from "lucide-react";
import { cn } from "@/lib/utils";

const navLinks = [
  { name: "Services", href: "/services" },
  { name: "Projects", href: "/projects" },
  { name: "Pricing", href: "/pricing" },
  { name: "About", href: "/about" },
  { name: "Blog", href: "/blogs" },
];

export default function Navbar() {
  const [isOpen, setIsOpen] = useState(false);
  const [scrolled, setScrolled] = useState(false);
  const [hidden, setHidden] = useState(false);
  const pathname = usePathname();

  useEffect(() => {
    let lastScroll = 0;

    const handleScroll = () => {
      const currentScroll = window.scrollY;

      setScrolled(currentScroll > 20);

      if (currentScroll > lastScroll && currentScroll > 100) {
        setHidden(true);
      } else {
        setHidden(false);
      }

      lastScroll = currentScroll;
    };

    window.addEventListener("scroll", handleScroll);
    return () => window.removeEventListener("scroll", handleScroll);
  }, []);

  return (
    <motion.nav
      initial={{ y: 0 }}
      animate={{ y: hidden ? -120 : 0 }}
      transition={{ duration: 0.4 }}
      className={cn(
        "fixed top-0 left-0 right-0 z-[100] transition-all duration-500 px-8 md:px-16",
        scrolled
          ? "py-5 bg-background/80 backdrop-blur-2xl border-b border-white/10 shadow-[0_8px_30px_rgba(0,0,0,0.3)]"
          : "py-8 bg-background/40 backdrop-blur-xl"
      )}
    >
      <div className="max-w-7xl mx-auto flex items-center justify-between">
        
        {/* Logo */}
        <Link href="/" className="flex items-center space-x-4 group">
          <div className="relative w-11 h-11 rounded-xl flex items-center justify-center font-bold text-white overflow-hidden group-hover:scale-110 transition-all duration-300">
            <div className="absolute inset-0 bg-gradient-to-br from-primary via-purple-500 to-pink-500"></div>
            <span className="relative z-10 font-extrabold">W</span>
          </div>
          <span className="text-2xl font-black tracking-tight text-white font-outfit">
            Webkaro
          </span>
        </Link>

        {/* Desktop Navigation */}
        <div className="hidden md:flex items-center w-full mx-auto space-x-12">
          <div className="flex items-center space-x-8 w-[90%]  flex items-center justify-end gap-12 ">
            {navLinks.map((link) => (
              <Link
                key={link.href}
                href={link.href}
                className="relative text-sm font-bold tracking-wide group"
              >
                <span
                  className={cn(
                    "transition-colors",
                    pathname === link.href
                      ? "text-white"
                      : "text-white/60 group-hover:text-white"
                  )}
                >
                  {link.name}
                </span>

                <span
                  className={cn(
                    "absolute -bottom-2 left-0 h-[2px] bg-primary transition-all duration-300",
                    pathname === link.href
                      ? "w-full"
                      : "w-0 group-hover:w-full"
                  )}
                />
              </Link>
            ))}
          </div>

        </div>

        {/* Mobile Toggle */}
        <button
          className="md:hidden text-white p-2.5 hover:bg-white/5 rounded-xl transition-colors"
          onClick={() => setIsOpen(!isOpen)}
        >
          {isOpen ? <X className="w-8 h-8" /> : <Menu className="w-8 h-8" />}
        </button>
      </div>

      {/* Mobile Menu */}
      <AnimatePresence>
        {isOpen && (
          <motion.div
            initial={{ opacity: 0, y: -20, scale: 0.95 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, y: -20, scale: 0.95 }}
            transition={{ duration: 0.3 }}
            className="absolute top-full left-6 right-6 bg-gradient-to-br from-background/95 to-background/80 backdrop-blur-3xl border border-white/10 mt-6 rounded-[2rem] md:hidden px-10 py-12 flex flex-col space-y-10 shadow-[0_20px_60px_rgba(0,0,0,0.6)]"
          >
            {navLinks.map((link) => (
              <Link
                key={link.href}
                href={link.href}
                onClick={() => setIsOpen(false)}
                className={cn(
                  "text-3xl font-black tracking-tight font-outfit transition-all hover:translate-x-2",
                  pathname === link.href
                    ? "text-primary"
                    : "text-white/70 hover:text-primary"
                )}
              >
                {link.name}
              </Link>
            ))}

            <Link
              href="/contact"
              onClick={() => setIsOpen(false)}
              className="w-full py-6 bg-gradient-to-r from-primary via-purple-500 to-pink-500 text-white rounded-2xl text-center font-black text-xl shadow-xl"
            >
              Start Your Project
            </Link>
          </motion.div>
        )}
      </AnimatePresence>
    </motion.nav>
  );
}
